// CategoryIcon returns an icon matching the given file Category.
func CategoryIcon(cat converter.Category) *ui.SVG {
	switch cat {
	case converter.CategoryImage:
		return IconImage
	case converter.CategorySpreadsheet, converter.CategoryData:
		return IconTable
	case converter.CategoryAudio:
		return IconMusic
	case converter.CategoryVideo:
		return IconFilm
	case converter.CategoryArchive:
		return IconArchive
	default:
		return IconFileText
	}
}
